using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Windows.Forms;
public class AdminProfile{public string Password,SSHConfig;}
static class OpenPanel{
 static bool Listening(){try{using(var s=new TcpClient()){var c=s.BeginConnect(IPAddress.Loopback,18780,null,null);bool ok=c.AsyncWaitHandle.WaitOne(300);if(ok)s.EndConnect(c);return ok;}}catch{return false;}}
 static Dictionary<string,object> Post(string path,object data,CookieContainer cookie,string csrf=null){var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:18780"+path);r.Proxy=null;r.Method="POST";r.CookieContainer=cookie;r.ContentType="application/json";r.Timeout=15000;if(csrf!=null)r.Headers["X-CSRF-Token"]=csrf;byte[] b=Encoding.UTF8.GetBytes(Common.Json.Serialize(data));r.ContentLength=b.Length;using(var s=r.GetRequestStream())s.Write(b,0,b.Length);using(var res=r.GetResponse())using(var reader=new StreamReader(res.GetResponseStream()))return Common.Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
 [STAThread]static int Main(string[] a){try{var profile=Common.Json.Deserialize<AdminProfile>(Common.Unprotect(File.ReadAllBytes(Path.Combine(Common.Base,"admin.dpapi")),"HomeRelayAdmin-v2"));if(!Listening()){if(!File.Exists(profile.SSHConfig))throw new Exception("找不到本机 SSH 管理配置。此工具不包含任何管理私钥。");var si=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32","OpenSSH","ssh.exe"),"-F "+Common.Q(profile.SSHConfig)+" -N -T -o ExitOnForwardFailure=yes -o ServerAliveInterval=15 -o ServerAliveCountMax=2 -L 127.0.0.1:18780:127.0.0.1:18780 website-prod"){UseShellExecute=false,CreateNoWindow=true};var proc=Process.Start(si);for(int i=0;i<100&&!Listening();i++){if(proc.HasExited)throw new Exception("私有 SSH 通道未能建立，请检查本机管理连接。");Thread.Sleep(150);}if(!Listening())throw new Exception("等待管理通道超时");}
  var cookies=new CookieContainer();var login=Post("/api/login",new{password=profile.Password},cookies);var link=Post("/api/link",new{},cookies,(string)login["csrf"]);string url=(string)link["url"];
  if(a.Length==2&&a[0]=="--link")File.WriteAllText(a[1],url);else Process.Start(new ProcessStartInfo(url){UseShellExecute=true});return 0;
 }catch(Exception e){if(a.Length>0){File.WriteAllText(Path.Combine(Common.Base,"open-error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"打开私有管理面板");return 1;}}
}
